---
import type { HTMLAttributes } from "astro/types"
import type { EmblaOptionsType } from "embla-carousel"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"section"> & {
  opts?: EmblaOptionsType
  orientation?: "horizontal" | "vertical"
}

const {
  class: className,
  opts,
  orientation = opts?.axis === "y" ? "vertical" : "horizontal",
  "aria-roledescription": roleDescription = "carousel",
  "data-slot": dataSlot = "carousel",
  // A named section is a region landmark. Without a name it would have no
  // role, so it becomes a group, the other container role the APG carousel
  // allows.
  role = Astro.props["aria-label"] || Astro.props["aria-labelledby"]
    ? undefined
    : "group",
  ...props
} = Astro.props

const resolvedOpts: EmblaOptionsType = {
  ...opts,
  axis: orientation === "horizontal" ? "x" : "y",
}
---

<section
  data-slot={dataSlot}
  data-orientation={orientation}
  data-carousel-options={JSON.stringify(resolvedOpts)}
  class={cn("group/carousel relative", className)}
  role={role}
  aria-roledescription={roleDescription}
  {...props}
>
  <slot />
</section>

<script>
  import EmblaCarousel, {
    type EmblaCarouselType,
    type EmblaOptionsType,
  } from "embla-carousel"

  type CarouselRoot = HTMLElement & {
    __fulldevCarouselApi?: EmblaCarouselType
  }

  const instances = new Map<CarouselRoot, () => void>()
  // A nested carousel owns its own parts. The data-carousel-* markers stay
  // in place when a caller overrides data-slot.
  const rootSelector = "[data-carousel-options]"
  const getParts = <T extends Element>(root: CarouselRoot, part: string) =>
    [...root.querySelectorAll<T>(`[data-carousel-${part}]`)].filter(
      (element) => element.closest(rootSelector) === root
    )
  const initialize = () => {
    for (const root of document.querySelectorAll<CarouselRoot>(rootSelector)) {
      if (instances.has(root)) continue
      const viewport = getParts<HTMLElement>(root, "viewport")[0]
      if (!viewport) continue
      const opts: EmblaOptionsType = JSON.parse(
        root.dataset.carouselOptions || "{}"
      )
      const api = EmblaCarousel(viewport, opts)
      root.__fulldevCarouselApi = api
      const previous = getParts<HTMLButtonElement>(root, "previous")
      const next = getParts<HTMLButtonElement>(root, "next")
      const emit = (type: "carousel:init" | "carousel:select") => {
        root.dispatchEvent(
          new CustomEvent(type, {
            detail: {
              api,
              canScrollPrev: api.canScrollPrev(),
              canScrollNext: api.canScrollNext(),
              selectedScrollSnap: api.selectedScrollSnap(),
              scrollSnapList: api.scrollSnapList(),
            },
          })
        )
      }
      const sync = () => {
        root.dataset.canScrollPrev = String(api.canScrollPrev())
        root.dataset.canScrollNext = String(api.canScrollNext())
        root.dataset.selectedScrollSnap = String(api.selectedScrollSnap())
        for (const button of previous)
          if (button.dataset.manualDisabled !== "true")
            button.disabled = !api.canScrollPrev()
        for (const button of next)
          if (button.dataset.manualDisabled !== "true")
            button.disabled = !api.canScrollNext()
        emit("carousel:select")
      }
      const jump = () =>
        window.matchMedia("(prefers-reduced-motion: reduce)").matches
      const onPrevious = () => api.scrollPrev(jump())
      const onNext = () => api.scrollNext(jump())
      const onKeyDown = (event: KeyboardEvent) => {
        const target = event.target
        if (
          event.defaultPrevented ||
          !(target instanceof Element) ||
          target.closest(rootSelector) !== root ||
          target.closest(
            'input, textarea, select, [contenteditable]:not([contenteditable="false"])'
          )
        )
          return
        const vertical = root.dataset.orientation === "vertical"
        switch (event.key) {
          case vertical ? "ArrowUp" : "ArrowLeft":
            onPrevious()
            break
          case vertical ? "ArrowDown" : "ArrowRight":
            onNext()
            break
          case "Home":
            api.scrollTo(0, jump())
            break
          case "End":
            api.scrollTo(api.scrollSnapList().length - 1, jump())
            break
          default:
            return
        }
        event.preventDefault()
      }
      for (const button of previous)
        button.addEventListener("click", onPrevious)
      for (const button of next) button.addEventListener("click", onNext)
      root.addEventListener("keydown", onKeyDown)
      api.on("select", sync)
      api.on("reInit", sync)
      sync()
      const frame = requestAnimationFrame(() => emit("carousel:init"))
      instances.set(root, () => {
        cancelAnimationFrame(frame)
        for (const button of previous)
          button.removeEventListener("click", onPrevious)
        for (const button of next) button.removeEventListener("click", onNext)
        root.removeEventListener("keydown", onKeyDown)
        api.off("select", sync)
        api.off("reInit", sync)
        api.destroy()
        delete root.__fulldevCarouselApi
      })
    }
  }
  initialize()
  document.addEventListener("astro:page-load", initialize)
  document.addEventListener("astro:before-swap", () => {
    for (const cleanup of instances.values()) cleanup()
    instances.clear()
  })
</script>

---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div">

const {
  class: className,
  "aria-roledescription": roleDescription = "slide",
  "data-slot": dataSlot = "carousel-item",
  role = "group",
  ...props
} = Astro.props
---

<div
  data-slot={dataSlot}
  role={role}
  aria-roledescription={roleDescription}
  class={cn(
    "min-w-0 shrink-0 grow-0 basis-full",
    "group-data-[orientation=horizontal]/carousel:pl-4",
    "group-data-[orientation=vertical]/carousel:pt-4",
    className
  )}
  {...props}
>
  <slot />
</div>

---
import type { HTMLAttributes } from "astro/types"
import ChevronRightIcon from "@lucide/astro/icons/chevron-right"

import { cn } from "@/lib/utils"
import { buttonVariants, type ButtonVariantProps } from "@/components/ui/button"

type Props = Omit<HTMLAttributes<"button">, "type"> & ButtonVariantProps

const {
  class: className,
  variant = "outline",
  size = "icon-sm",
  disabled,
  "data-slot": dataSlot = "carousel-next",
  ...props
} = Astro.props
---

<button
  type="button"
  data-slot={dataSlot}
  data-carousel-next
  data-variant={variant}
  data-size={size}
  data-manual-disabled={disabled ? "true" : undefined}
  disabled={disabled}
  class={cn(
    buttonVariants({ variant, size }),
    "rounded-2xl absolute touch-manipulation group-data-[orientation=horizontal]/carousel:inset-y-0 group-data-[orientation=horizontal]/carousel:-right-12 group-data-[orientation=horizontal]/carousel:my-auto",
    "group-data-[orientation=vertical]/carousel:right-auto group-data-[orientation=vertical]/carousel:-bottom-12 group-data-[orientation=vertical]/carousel:left-1/2 group-data-[orientation=vertical]/carousel:-translate-x-1/2 group-data-[orientation=vertical]/carousel:translate-y-0 group-data-[orientation=vertical]/carousel:rotate-90",
    className
  )}
  {...props}
>
  <slot>
    <ChevronRightIcon aria-hidden="true" />
    <span class="sr-only">Next slide</span>
  </slot>
</button>

